// Pull the first NDA-shaped attachment, base64-encode it, and normalize the
// envelope fields the downstream prompt needs. Reject mail with no usable file.
const item = $json;
const binary = $binary || {};
const attachmentKey = Object.keys(binary).find(k => /\.(pdf|docx)$/i.test(binary[k].fileName || ''));

if (!attachmentKey) {
  // Surface as a structured 'no_attachment' record so the routing IF can divert it.
  return [{
    json: {
      status: 'no_attachment',
      sender: (item.from || '').replace(/.*<|>.*/g, ''),
      subject: item.subject || '',
      thread_id: item.threadId,
      message_id: item.id,
    }
  }];
}

const file = binary[attachmentKey];
const sender = (item.from || '').match(/<([^>]+)>/)?.[1] || (item.from || '').trim();
const senderDomain = sender.split('@').pop()?.toLowerCase() || '';

return [{
  json: {
    status: 'have_attachment',
    sender,
    sender_domain: senderDomain,
    subject: item.subject || '',
    body_snippet: (item.snippet || '').slice(0, 2000),
    received_at: item.internalDate ? new Date(Number(item.internalDate)).toISOString() : new Date().toISOString(),
    thread_id: item.threadId,
    message_id: item.id,
    attachment_filename: file.fileName,
    attachment_mime: file.mimeType,
    attachment_size: file.fileSize,
    attachment_b64: file.data,
  }
}];

// Merge the intake payload with the counterparty row (or default unknown).
const intake = $('Normalize Intake').item.json;
const registry = $json || {};

const risk_tier = registry.risk_tier || 'unknown';
const counterparty_name = registry.counterparty_name || intake.sender_domain;

return [{
  json: {
    ...intake,
    counterparty_id: registry.counterparty_id || null,
    counterparty_name,
    risk_tier,
    preferred_paper: registry.preferred_paper || 'unknown',
    registry_notes: registry.notes || null,
  }
}];

