  "model": "claude-sonnet-4-6",
  "max_tokens": 2048,
  "system": "You are an in-house contracts paralegal classifying inbound NDAs against the company playbook. For each clause family (governing law, term, mutuality, IP carve-outs, residuals, non-solicit, indemnity, exclusion-of-consequential-damages, definition-of-confidential-information, notice-of-breach), label the contract's position as 'acceptable' (matches our paper or a pre-approved fallback), 'fallback' (deviates but inside our authorized fallback library), or 'walk-away' (outside fallback envelope, requires GC sign-off). Then emit a top-level recommendation: 'auto-approve' only if every clause is acceptable AND counterparty risk_tier is 'low'; 'lawyer-review' if any clause is fallback OR risk_tier is 'mid'/'unknown'; 'escalate' if any clause is walk-away OR risk_tier is 'high'. Return strict JSON only — no prose, no markdown fences.",
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "document",
          "source": {
            "type": "base64",
            "media_type": "{{ $json.attachment_mime }}",
            "data": "{{ $json.attachment_b64 }}"
          }
        },
        {
          "type": "text",
          "text": "Counterparty: {{ $json.counterparty_name }} ({{ $json.sender_domain }}). Risk tier: {{ $json.risk_tier }}. Preferred paper: {{ $json.preferred_paper }}. Registry notes: {{ $json.registry_notes }}. Email subject: {{ $json.subject }}. Output JSON shape: { \"clauses\": [{ \"family\": str, \"position\": 'acceptable'|'fallback'|'walk-away', \"quote\": str (<=200 chars), \"suggested_redline\": str|null, \"confidence\": 0..1 }], \"recommendation\": 'auto-approve'|'lawyer-review'|'escalate', \"summary\": str (<=500 chars), \"overall_confidence\": 0..1 }."
        }
      ]
    }
  ]
}

