// Parse the Claude response, apply the conservative-tier override, and stamp
// the routing decision used by every downstream branch.
const intake = $('Merge Counterparty Context').item.json;
const raw = $json.content?.[0]?.text || '';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  // Hard-fail to escalate when we cannot parse — never silently auto-approve.
  return [{
    json: {
      ...intake,
      recommendation: 'escalate',
      escalation_reason: 'parser_error',
      raw_response: raw.slice(0, 1000),
      clauses: [],
      summary: 'Claude response was not valid JSON. Manual review required.',
      overall_confidence: 0,
    }
  }];
}

// Conservative override: any walk-away clause OR confidence < 0.7 forces escalate.
const hasWalkAway = (parsed.clauses || []).some(c => c.position === 'walk-away');
const hasFallback = (parsed.clauses || []).some(c => c.position === 'fallback');
const lowConfidence = (parsed.overall_confidence ?? 0) < 0.7;

let recommendation = parsed.recommendation;
let override_reason = null;
if (hasWalkAway) {
  recommendation = 'escalate';
  override_reason = 'walk_away_clause';
} else if (lowConfidence && recommendation === 'auto-approve') {
  recommendation = 'lawyer-review';
  override_reason = 'low_confidence';
} else if (intake.risk_tier !== 'low' && recommendation === 'auto-approve') {
  recommendation = 'lawyer-review';
  override_reason = 'non_low_risk_tier';
}

return [{
  json: {
    ...intake,
    recommendation,
    override_reason,
    has_walk_away: hasWalkAway,
    has_fallback: hasFallback,
    clauses: parsed.clauses || [],
    summary: parsed.summary || '',
    overall_confidence: parsed.overall_confidence ?? 0,
  }
}];

